class AsyncAgentsApi(AsyncKonApi):
    """kon-agents

    Agent permissions, keys and quotas (admin only).
    """

    kon = "kon-agents"

    async def agent_access(self, *, id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[AgentAccessResult]:
        """What an agent can do

        The merged view (broad ∪ fine-grained − denied) of the agent's saved scopes: every SDK operation and every dataset action with its state and the scope that decided it.

        REST: `GET /api/v1/agents/{id}/access` · scope `kon:agents:agent-access`
        idempotent (safe to retry)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["agent-access"], {"id": id}, None, request_options)

    async def agent_decisions(self, *, days: Optional[int] = None, agent_id: Optional[Union[str, int]] = None, limit: Optional[int] = None, offset: Optional[int] = None, request_options: Optional[RequestOptions] = None) -> Outcome[AgentDecisionsResult]:
        """What agents chose not to do, and why

        Decisions agents recorded themselves (MCP kitsuden_record_decision, POST /api/agent/decisions): the action they discarded, the reason, the alternatives and the version of the agent that decided, newest first, over the last `days` (1-365, default 30). Read-only: nobody edits a decision. Admins see every agent; an editor sees the agents whose proposals they may decide, so not the ones they sponsor.

        REST: `GET /api/v1/agent-decisions` · scope `kon:agents:agent-decisions`
        idempotent (safe to retry)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["agent-decisions"], {"days": days, "agentId": agent_id, "limit": limit, "offset": offset}, None, request_options)

    def iter_agent_decisions(self, *, days: Optional[int] = None, agent_id: Optional[Union[str, int]] = None, limit: Optional[int] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[Any]:
        """Every item of `agent_decisions`, page after page (moves `offset`).

        Stops on an empty or short page, or when the response says there is no more. Raises `ProposalPendingError` if a page needs human approval.
        """
        return self._iterate(OPERATIONS["agent-decisions"], {"days": days, "agentId": agent_id, "limit": limit}, request_options)

    async def agent_friction(self, *, days: Optional[int] = None, agent_id: Optional[Union[str, int]] = None, request_options: Optional[RequestOptions] = None) -> Outcome[AgentFrictionResult]:
        """Where agents get stuck with the MCP tools

        Per tool, over the last `days` (1-90, default 7): calls, failures by error code, keys agents invent, rejected proposals, and what to change in the operation's `guide`. Reads the audited MCP tool calls; argument values are never stored, only their names.

        REST: `GET /api/v1/agent-friction` · scope `kon:agents:agent-friction`
        idempotent (safe to retry)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["agent-friction"], {"days": days, "agentId": agent_id}, None, request_options)

